-- Turkey: ES/DE/FR milestone translations for the 4 milestones in
-- migration 299. Hand-translated, not machine copy-paste.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-efatura-2014', 'es', 'e-Fatura se vuelve obligatoria para los grandes contribuyentes', 'A partir del 1 de abril de 2014, la Administración Tributaria de Turquía (Gelir İdaresi Başkanlığı, GİB) hizo obligatoria la e-Fatura para las empresas con una facturación superior a 5 millones de TRY, junto con varios sectores obligados con independencia de su tamaño: empresas energéticas, mayoristas de frutas y verduras, mercados y proveedores de servicios en línea, e importadores. La e-Fatura funciona como un modelo de validación (clearance): el vendedor envía una factura estructurada en UBL-TR y firmada digitalmente a la plataforma central de la GİB, que la valida y distribuye la factura validada al comprador registrado — vendedor y comprador nunca intercambian el documento directamente. Esto se apoyó en los trabajos de transformación digital que la GİB venía realizando desde 2012.', '["No se requiere ninguna acción para este hito histórico — se incluye como contexto de las entradas siguientes", "Las empresas que ya superen el umbral de 5 millones de TRY, o que pertenezcan a uno de los sectores siempre obligados, deben confirmar su registro en e-Fatura si aún no lo han hecho"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-efatura-2014', 'de', 'e-Fatura wird für größere Steuerpflichtige verpflichtend', 'Ab dem 1. April 2014 machte die türkische Steuerbehörde (Gelir İdaresi Başkanlığı, GİB) e-Fatura für Unternehmen mit einem Umsatz von über 5 Millionen TRY verpflichtend, zusammen mit mehreren Branchen, die unabhängig von ihrer Größe verpflichtet sind — Energieunternehmen, Obst- und Gemüsegroßhändler, Online-Marktplätze und -Dienstleister sowie Importeure. e-Fatura funktioniert als Freigabemodell (Clearance): Der Verkäufer übermittelt eine strukturierte, digital signierte UBL-TR-Rechnung an die zentrale Plattform der GİB, die sie prüft und die freigegebene Rechnung an den registrierten Käufer verteilt — Verkäufer und Käufer tauschen das Dokument nie direkt aus. Dies baute auf den E-Transformations-Grundlagen auf, die die GİB seit 2012 gelegt hatte.', '["Für diesen historischen Meilenstein ist noch keine Handlung erforderlich — er dient als Kontext für die folgenden Einträge", "Unternehmen, die bereits über der Schwelle von 5 Millionen TRY liegen oder zu einer der stets verpflichteten Branchen gehören, sollten ihre e-Fatura-Registrierung bestätigen, falls noch nicht geschehen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-efatura-2014', 'fr', 'L''e-Fatura devient obligatoire pour les plus grands contribuables', 'À compter du 1er avril 2014, l''administration fiscale turque (Gelir İdaresi Başkanlığı, GİB) a rendu l''e-Fatura obligatoire pour les entreprises dont le chiffre d''affaires dépasse 5 millions de TRY, ainsi que pour plusieurs secteurs soumis à l''obligation quelle que soit leur taille — sociétés énergétiques, grossistes en fruits et légumes, places de marché et prestataires de services en ligne, et importateurs. L''e-Fatura fonctionne selon un modèle de validation (clearance) : le vendeur transmet une facture structurée au format UBL-TR et signée électroniquement à la plateforme centrale de la GİB, qui la valide et distribue la facture validée à l''acheteur enregistré — vendeur et acheteur n''échangent jamais directement le document. Cette étape s''appuyait sur les travaux de transformation numérique menés par la GİB depuis 2012.', '["Aucune action n''est requise pour ce jalon historique — il est fourni à titre de contexte pour les entrées suivantes", "Les entreprises déjà au-dessus du seuil de 5 millions de TRY, ou relevant de l''un des secteurs toujours soumis à l''obligation, doivent confirmer leur inscription à l''e-Fatura si ce n''est pas déjà fait"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-edefter-2015', 'es', 'e-Defter (libros contables electrónicos) se vuelve obligatorio junto con la e-Fatura', 'A partir de 2015, e-Defter — los libros mayores y diarios contables electrónicos, presentados a la GİB en un formato estándar basado en XBRL — se volvió obligatorio para todo usuario de e-Fatura, así como para las empresas sujetas a auditoría independiente conforme a los umbrales del Código de Comercio turco. Se trata de una obligación contable adicional sobre la e-Fatura, no de un cambio en el alcance del propio mandato de facturación.', '["No se requiere ninguna acción para este hito histórico — se incluye como contexto", "Toda empresa que ya utilice la e-Fatura debe confirmar que sus presentaciones de e-Defter están al día"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-edefter-2015', 'de', 'e-Defter (elektronische Bücher) wird neben e-Fatura verpflichtend', 'Ab 2015 wurde e-Defter — elektronische Haupt- und Journalbücher, die der GİB in einem standardisierten XBRL-basierten Format übermittelt werden — für jeden e-Fatura-Nutzer verpflichtend, ebenso wie für Unternehmen, die nach den Schwellenwerten des türkischen Handelsgesetzbuchs einer unabhängigen Prüfung unterliegen. Dies ist eine zusätzliche Buchführungspflicht, die auf e-Fatura aufsetzt, keine Änderung des Umfangs der Rechnungspflicht selbst.', '["Für diesen historischen Meilenstein ist noch keine Handlung erforderlich — er dient als Kontext", "Jedes Unternehmen, das bereits e-Fatura nutzt, sollte prüfen, ob seine e-Defter-Einreichungen aktuell sind"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-edefter-2015', 'fr', 'L''e-Defter (livres comptables électroniques) devient obligatoire aux côtés de l''e-Fatura', 'À partir de 2015, l''e-Defter — grands livres et journaux comptables électroniques, transmis à la GİB dans un format standard basé sur XBRL — est devenu obligatoire pour tout utilisateur de l''e-Fatura, ainsi que pour les entreprises soumises à un audit indépendant selon les seuils du Code de commerce turc. Il s''agit d''une obligation comptable qui s''ajoute à l''e-Fatura, et non d''une modification du périmètre de l''obligation de facturation elle-même.', '["Aucune action n''est requise pour ce jalon historique — il est fourni à titre de contexte", "Toute entreprise utilisant déjà l''e-Fatura doit vérifier que ses déclarations e-Defter sont à jour"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-ewaybill-2023', 'es', 'e-İrsaliye (albarán electrónico) se vuelve obligatorio por encima de un umbral de facturación', 'A partir del 1 de julio de 2023, el e-İrsaliye — el albarán/nota de despacho electrónico de Turquía que acompaña el movimiento físico de las mercancías — se volvió obligatorio para los contribuyentes con una facturación superior a 10 millones de TRY, quedando abierta la adhesión voluntaria para el resto. El e-İrsaliye documenta el movimiento de la mercancía en sí, no la venta, por lo que coexiste con la e-Fatura en lugar de sustituir ninguna parte de ella — una empresa puede cumplir plenamente con la e-Fatura y aun así necesitar implementar el e-İrsaliye por separado al superar este umbral.', '["Confirme si su facturación ha superado el umbral de 10 millones de TRY del e-İrsaliye, de forma independiente a cualquier comprobación del umbral de la e-Fatura", "Si despacha mercancías por encima del umbral, integre la emisión de e-İrsaliye junto a sus sistemas actuales de e-Fatura/e-Arşiv — es un tipo de documento distinto, no una variante de la factura"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-ewaybill-2023', 'de', 'e-İrsaliye (elektronischer Lieferschein) wird oberhalb eines Umsatzschwellenwerts verpflichtend', 'Ab dem 1. Juli 2023 wurde e-İrsaliye — der elektronische Liefer-/Versandschein der Türkei, der die physische Warenbewegung begleitet — für Steuerpflichtige mit einem Umsatz von über 10 Millionen TRY verpflichtend; für alle anderen bleibt die freiwillige Nutzung offen. e-İrsaliye dokumentiert die Warenbewegung selbst und nicht den Verkauf, steht also neben e-Fatura, statt einen Teil davon zu ersetzen — ein Unternehmen kann vollständig e-Fatura-konform sein und muss dennoch e-İrsaliye separat einführen, sobald es diese Schwelle überschreitet.', '["Prüfen Sie, ob Ihr Umsatz die e-İrsaliye-Schwelle von 10 Millionen TRY überschritten hat — unabhängig von einer etwaigen Prüfung der e-Fatura-Schwelle", "Wenn Sie Waren oberhalb der Schwelle versenden, integrieren Sie die e-İrsaliye-Ausstellung zusätzlich zu Ihren bestehenden e-Fatura-/e-Arşiv-Systemen — es handelt sich um einen eigenständigen Dokumenttyp, nicht um eine Variante der Rechnung"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-ewaybill-2023', 'fr', 'L''e-İrsaliye (bon de livraison électronique) devient obligatoire au-delà d''un seuil de chiffre d''affaires', 'À compter du 1er juillet 2023, l''e-İrsaliye — le bon de livraison/d''expédition électronique turc accompagnant le mouvement physique des marchandises — est devenu obligatoire pour les contribuables dont le chiffre d''affaires dépasse 10 millions de TRY, l''adoption volontaire restant ouverte à tous les autres. L''e-İrsaliye documente le mouvement de la marchandise elle-même, et non la vente, de sorte qu''il s''ajoute à l''e-Fatura plutôt que de s''y substituer — une entreprise peut être pleinement conforme à l''e-Fatura et devoir malgré tout mettre en place l''e-İrsaliye séparément une fois ce seuil franchi.', '["Vérifiez si votre chiffre d''affaires a franchi le seuil de 10 millions de TRY de l''e-İrsaliye, indépendamment de toute vérification du seuil de l''e-Fatura", "Si vous expédiez des marchandises au-delà de ce seuil, intégrez l''émission de l''e-İrsaliye en plus de vos systèmes e-Fatura/e-Arşiv existants — il s''agit d''un type de document distinct, non d''une variante de la facture"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-earsiv-threshold-2026', 'es', 'Se elimina el umbral mínimo de la e-Arşiv; los umbrales de 2026 se endurecen aún más', 'A partir del 1 de enero de 2026, la GİB eliminó por completo el anterior umbral mínimo para la emisión obligatoria de e-Arşiv — cualquier factura dirigida a un destinatario no registrado en e-Fatura debe emitirse ahora electrónicamente como factura e-Arşiv, sea cual sea su importe, cerrando lo que hasta entonces era un vacío real para las operaciones de bajo valor. Junto con esto, el umbral de facturación de e-Fatura para 2026, calculado sobre los ingresos de 2025, es de 3 millones de TRY con carácter general, con un umbral inferior de 500.000 TRY aplicable a las empresas de comercio electrónico y a las operaciones inmobiliarias, de vehículos a motor y de alojamiento con licencia. El registro de las empresas que superen cualquiera de los dos umbrales según los ingresos de 2025 vence el 1 de julio de 2026.', '["Compruebe su facturación de 2025 frente al umbral general de 3 millones de TRY, o el umbral inferior de 500.000 TRY si opera en comercio electrónico, inmobiliario, vehículos a motor o alojamiento con licencia", "Si supera cualquiera de los dos umbrales, regístrese en e-Fatura antes del 1 de julio de 2026", "Si no supera el umbral de la e-Fatura, confirme que su sistema de facturación emite ahora toda factura e-Arşiv de forma electrónica — la anterior excepción en papel para operaciones de bajo valor ya no se aplica"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-earsiv-threshold-2026', 'de', 'Die Wertgrenze der e-Arşiv entfällt; die Schwellenwerte für 2026 verschärfen sich weiter', 'Ab dem 1. Januar 2026 hob die GİB die bisherige Wertgrenze für die verpflichtende e-Arşiv-Ausstellung vollständig auf — jede Rechnung an einen nicht bei e-Fatura registrierten Empfänger muss nun unabhängig vom Betrag elektronisch als e-Arşiv-Rechnung ausgestellt werden, womit eine bislang bestehende Lücke bei Kleinbeträgen geschlossen wird. Gleichzeitig liegt die e-Fatura-Umsatzschwelle für 2026, bezogen auf den Umsatz 2025, allgemein bei 3 Millionen TRY, mit einer niedrigeren Schwelle von 500.000 TRY für E-Commerce-Unternehmen sowie für Immobilien-, Kraftfahrzeug- und lizenzierte Beherbergungsgeschäfte. Die Registrierung für Unternehmen, die auf Basis des Umsatzes 2025 eine der beiden Schwellen überschreiten, ist bis zum 1. Juli 2026 fällig.', '["Prüfen Sie Ihren Umsatz 2025 anhand der allgemeinen Schwelle von 3 Millionen TRY oder der niedrigeren Schwelle von 500.000 TRY, wenn Sie im E-Commerce, in der Immobilienbranche, im Kraftfahrzeugbereich oder in lizenzierten Beherbergungsbetrieben tätig sind", "Wenn Sie eine der beiden Schwellen überschreiten, registrieren Sie sich bis zum 1. Juli 2026 für e-Fatura", "Wenn Sie die e-Fatura-Schwelle nicht überschreiten, stellen Sie sicher, dass Ihr Rechnungssystem jetzt jede e-Arşiv-Rechnung elektronisch ausstellt — die bisherige Papierausnahme für Kleinbeträge gilt nicht mehr"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tr-earsiv-threshold-2026', 'fr', 'Le seuil minimal de l''e-Arşiv est supprimé ; les seuils de 2026 se resserrent encore', 'À compter du 1er janvier 2026, la GİB a totalement supprimé le seuil minimal auparavant applicable à l''émission obligatoire de l''e-Arşiv — toute facture adressée à un destinataire non enregistré à l''e-Fatura doit désormais être émise électroniquement sous forme de facture e-Arşiv, quel que soit son montant, comblant ainsi une véritable lacune pour les opérations de faible valeur. Parallèlement, le seuil de chiffre d''affaires de l''e-Fatura pour 2026, calculé sur les revenus de 2025, est fixé à 3 millions de TRY de manière générale, avec un seuil inférieur de 500 000 TRY applicable aux entreprises de commerce électronique ainsi qu''aux opérations immobilières, de véhicules à moteur et d''hébergement agréé. L''inscription des entreprises franchissant l''un ou l''autre seuil sur la base des revenus 2025 doit intervenir avant le 1er juillet 2026.', '["Vérifiez votre chiffre d''affaires 2025 par rapport au seuil général de 3 millions de TRY, ou au seuil inférieur de 500 000 TRY si vous exercez dans le commerce électronique, l''immobilier, les véhicules à moteur ou l''hébergement agréé", "Si vous franchissez l''un ou l''autre seuil, inscrivez-vous à l''e-Fatura avant le 1er juillet 2026", "Si vous ne franchissez pas le seuil de l''e-Fatura, vérifiez que votre système de facturation émet désormais chaque facture e-Arşiv par voie électronique — l''ancienne dérogation papier pour les faibles montants ne s''applique plus"]');
